@charset "UTF-8";
body {
  padding-top: 64px;
  background-color: #cccccc;
}

h1 {
  text-align: center;
}

#result {
  font-size: 24px;
  width: 400px;
  margin: auto;
}

#result::after {
  content: "クッキー：" counter(cookies) "枚";
}

#game-clear {
  position: fixed;
  inset: 0;
  width: 100%;
  height: 100vh;
  line-height: 100vh;
  text-align: center;
  background-color: rgba(0, 0, 0, 0.8);
  color: white;
  font-size: 60px;
  font-weight: bold;
  display: none;
}

#main {
  position: relative;
  counter-reset: cookies 0;
  width: fit-content;
  display: flex;
  margin: auto;
  align-items: center;
}
#main #cookie {
  font-size: 200px;
  line-height: 200px;
  width: 200px;
  height: 100%;
}
#main > .click-group {
  position: absolute;
  inset: 50% auto auto 0;
  transform: translateY(-50%);
  width: 200px;
  height: 200px;
  visibility: hidden;
  pointer-events: none;
}
#main > .click-group > input.increment {
  position: absolute;
  inset: 0;
  width: 200px;
  height: 200px;
  margin: 0;
  appearance: none;
  border: none;
  border-radius: 50%;
  cursor: pointer;
}
#main > .click-group > input.increment:focus-visible {
  outline: 2px solid black;
  outline-offset: 2px;
}
#main > .click-group > input.increment:checked {
  left: 500px;
}

#shop {
  width: 200px;
  border: 1px dotted black;
  padding: 10px;
}
#shop > #items {
  margin-top: 10px;
  display: flex;
  flex-direction: column;
  gap: 10px;
}
#shop > #items > div > input {
  position: absolute;
  left: 500px;
  appearance: none;
}
#shop > #items > div > .purchase {
  width: 100%;
  background-color: var(--purchase-background, gray);
  cursor: var(--purchase-cursor, not-allowed);
  border: none;
  position: relative;
  height: 30px;
  text-align: center;
}
#shop > #items > div > .purchase > input.item {
  width: 100%;
  height: 100%;
  position: absolute;
  inset: 0;
  z-index: 1;
  margin: 0;
  opacity: 0;
  visibility: var(--purchase-visibility, hidden);
  cursor: pointer;
}
#shop > #items > div > .purchase > span {
  line-height: 30px;
}
#shop > #items > div > .purchase:has(> input.item:focus-visible) {
  outline: 2px solid black;
  outline-offset: 2px;
}

#main > .click-group.rate-1 > input.increment:checked {
  counter-increment: cookies 1;
}

#main > .click-group.rate-2 > input.increment:checked {
  counter-increment: cookies 2;
}

#main > .click-group.rate-3 > input.increment:checked {
  counter-increment: cookies 3;
}

#main > .click-group.rate-4 > input.increment:checked {
  counter-increment: cookies 4;
}

#main > .click-group.rate-5 > input.increment:checked {
  counter-increment: cookies 5;
}

